{
  "headline": "FDA's records trace our supply to a plant classified VAI 346 days before the shortage posting and a Warning Letter 1007 days before the posting",
  "headline_cites": ["D4", "D5"],
  "sentences": [
    {
      "text": "FDA posted the leucovorin calcium shortage on 2012-01-01 and as of 2026-10-21 it has been on the list for 178 months.",
      "cites": ["D9"]
    },
    {
      "text": "A Warning Letter was issued to Hikma Pharmaceuticals USA Inc. (FEI 1510690) on 2009-03-30, which was 1007 days before the shortage posting.",
      "cites": ["D4", "E13", "E14"]
    },
    {
      "text": "An FDA inspection of the same plant ended 2011-01-20 and was classified VAI, 346 days before the shortage posting.",
      "cites": ["D5", "E10"]
    },
    {
      "text": "Subsequent inspections of that plant in 2014, 2018, and 2026 were also classified VAI or NAI.",
      "cites": ["E11", "E12", "E15"]
    },
    {
      "text": "Another registered plant for this product, Cerbios-Pharma SA (FEI 3002808250), received a VAI classification on 2024-03-07.",
      "cites": ["E8", "E9"]
    },
    {
      "text": "The rule-based transfer option ranked 1 moves 8 units from Corvale Lakeside (24 days on hand) to Corvale East (7 days on hand), raising East to 8 days on hand.",
      "cites": ["D1", "D3", "D6"]
    }
  ]
}
